<?php
declare(strict_types=1);

namespace App\Services;

use App\Models\BusinessInsight;
use App\Models\Tenant;
use App\Odoo\OdooFactory;
use App\Tenancy\TenantContext;
use Illuminate\Support\Facades\Log;

/**
 * Client Strategic Analysis — a holistic, cross-functional strategic audit of a
 * client's business, generated by Claude from a consolidated snapshot of every
 * available lens (financial, liquidity, receivables, payables, inventory,
 * operations). Produces a concise narrative diagnosis, a prioritized action
 * table, and a 90-day roadmap.
 *
 * Evolves the Business Insights infrastructure: reuses BusinessInsightsService's
 * defensive per-tenant KPI gather for the core blocks, layers on the extra
 * dimensions, and persists to the existing BusinessInsight table (narrative in
 * insight_md; action table + roadmap + scorecard live in kpis_snapshot) so no
 * new migration is required.
 */
final class StrategicAnalysisService
{
    private const ANTHROPIC_VERSION = '2023-06-01';
    private const TIMEOUT_SECONDS   = 90;
    public  const KIND              = 'strategic';   // stored in kpis_snapshot._kind

    public function __construct(private TenantContext $context) {}

    /**
     * Consolidated holistic snapshot for a tenant. Reuses the Business Insights
     * gather (revenue / P&L / receivables / reconciliation) and adds the
     * treasury, payables, and inventory lenses — each guarded so a missing
     * module or a flaky Odoo call never sinks the whole audit.
     */
    public function aggregate(Tenant $tenant): array
    {
        $base = app(BusinessInsightsService::class)->aggregateKpis($tenant);

        // Everything else runs inside the tenant context too.
        $previous = $this->context->has() ? $this->context->tenant() : null;
        $this->context->set($tenant);

        $extra = ['treasury' => null, 'payables' => null, 'inventory' => null, 'operations' => null];
        try {
            $client   = OdooFactory::fromConfig();
            $ccy      = (string) ($base['currency'] ?? 'XAF');
            $revYtd   = (float) ($base['revenue']['total'] ?? 0);
            $daysYtd  = max(1, (int) ($base['revenue']['days'] ?? 1));

            // Expenses for DPO — from the P&L block if present.
            $pl = $base['pl'] ?? [];
            $totalExp = max(1.0, (float) ($pl['cogs'] ?? 0) + (float) ($pl['opex'] ?? 0));

            if ($tenant->moduleEnabled('treasury') || $tenant->moduleEnabled('working_capital')) {
                $extra['treasury'] = $this->guard(fn () => $this->trimTreasury((new WorkingCapitalService($client))->analyze()));
            }
            if ($tenant->moduleEnabled('payables')) {
                $extra['payables'] = $this->guard(fn () => $this->trimPayables((new PayablesService($client))->analyze($totalExp, 365, $ccy)));
            }
            if ($tenant->moduleEnabled('inventory')) {
                $extra['inventory'] = $this->guard(fn () => $this->trimInventory((new InventoryService($client))->analyze(new \DateTimeImmutable())));
            }
            if ($tenant->moduleEnabled('operations')) {
                $extra['operations'] = $this->guard(fn () => $this->trimOperations((new OperationsService($client))->analyze()));
            }
        } catch (\Throwable $e) {
            $base['errors'][] = 'strategic-extra: ' . $e->getMessage();
        }

        if ($previous) $this->context->set($previous); else $this->context->clear();

        return array_merge($base, $extra, ['_kind' => self::KIND]);
    }

    /**
     * Generate + persist a strategic analysis for $tenant. Always returns a
     * BusinessInsight row; on failure the row carries status failed/skipped so
     * the admin can see what happened.
     */
    public function generate(Tenant $tenant, bool $force = false): BusinessInsight
    {
        // One per calendar month unless forced.
        if (!$force) {
            $monthStart = now()->startOfMonth();
            $existing = BusinessInsight::where('tenant_id', $tenant->id)
                ->where('generated_at', '>=', $monthStart)
                ->whereJsonContains('kpis_snapshot->_kind', self::KIND)
                ->orderByDesc('generated_at')->first();
            if ($existing) return $existing;
        }

        $snapshot = $this->aggregate($tenant);
        $snapshot['scorecard'] = BusinessInsightsScorer::score($snapshot);

        $hasData = ($snapshot['revenue'] ?? null) !== null || ($snapshot['pl'] ?? null) !== null
                || ($snapshot['receivables'] ?? null) !== null || ($snapshot['inventory'] ?? null) !== null;
        if (!$hasData) {
            return $this->persist($tenant, '—', $snapshot, 'No Odoo data available yet — sync first.', BusinessInsight::PRIORITY_WATCH, BusinessInsight::STATUS_SKIPPED, $snapshot['errors'][0] ?? null);
        }

        $apiKey = (string) config_env('AI_API_KEY', '');
        $model  = (string) (config('bi.strategic.model') ?: config_env('AI_MODEL', '') ?: 'claude-sonnet-4-20250514');
        if ($apiKey === '') {
            return $this->persist($tenant, $model, $snapshot, 'AI provider not configured — set AI_API_KEY.', BusinessInsight::PRIORITY_WATCH, BusinessInsight::STATUS_FAILED, 'AI_API_KEY missing');
        }

        try {
            [$raw, $usage] = $this->callAnthropic($apiKey, $model, $snapshot);
            $parsed = $this->parseResponse($raw);
            // Fold the structured action table + roadmap into the snapshot JSON.
            $snapshot['action_table'] = $parsed['actions'];
            $snapshot['roadmap_90d']  = $parsed['roadmap'];

            $row = $this->persist($tenant, $model, $snapshot, $parsed['summary'], $parsed['priority'], BusinessInsight::STATUS_OK, null, $parsed['narrative_md']);
            $row->input_tokens  = $usage['input']  ?? 0;
            $row->output_tokens = $usage['output'] ?? 0;
            $row->save();
            return $row;
        } catch (\Throwable $e) {
            Log::error('StrategicAnalysis generate failed for ' . $tenant->slug . ': ' . $e->getMessage());
            return $this->persist($tenant, $model, $snapshot, 'Generation failed — see error_msg.', BusinessInsight::PRIORITY_WATCH, BusinessInsight::STATUS_FAILED, substr($e->getMessage(), 0, 480));
        }
    }

    private function persist(Tenant $t, string $model, array $snapshot, string $summary, string $priority, string $status, ?string $err, string $md = ''): BusinessInsight
    {
        return BusinessInsight::create([
            'tenant_id'     => $t->id,
            'generated_at'  => now(),
            'model'         => $model,
            'kpis_snapshot' => $snapshot,
            'insight_md'    => $md,
            'summary'       => $summary,
            'priority'      => $priority,
            'status'        => $status,
            'error_msg'     => $err,
        ]);
    }

    private function guard(\Closure $fn)
    {
        try { return $fn(); } catch (\Throwable $e) { return null; }
    }

    // ── Trim helpers for the added lenses ───────────────────────────────
    private function trimTreasury(array $t): array
    {
        $r = $t['ratios'] ?? [];
        $out = [];
        foreach (['dso', 'dpo', 'ccc', 'current', 'quick', 'cash'] as $k) $out[$k] = $r[$k] ?? null;
        $out['cash_on_hand'] = $t['components']['cash'] ?? ($t['cash'] ?? null);
        return $out;
    }
    private function trimPayables(array $p): array
    {
        $k = $p['kpis'] ?? [];
        return ['total_ap' => $k['total_ap'] ?? 0, 'overdue_ap' => $k['overdue_ap'] ?? 0, 'dpo_days' => $k['dpo_days'] ?? null, 'overdue_rate_pct' => $k['overdue_rate_pct'] ?? 0, 'top5_pct' => $k['top5_concentration_pct'] ?? 0];
    }
    private function trimInventory(array $i): array
    {
        $d = $i['inventory_days'] ?? [];
        return ['ending_inventory' => $d['ending_inventory'] ?? 0, 'cogs_ytd' => $d['cogs_ytd'] ?? 0, 'days_outstanding' => $d['days_outstanding'] ?? 0];
    }
    private function trimOperations(array $o): array
    {
        $sr = $o['kpis']['scan_revenue'] ?? [];
        return ['scan_revenue' => $sr['value'] ?? ($sr['current'] ?? null), 'containers_scanned' => $o['kpis']['containers_scanned']['value'] ?? null, 'scan_rate' => $o['kpis']['scan_rate']['value'] ?? null];
    }

    // ── Claude ──────────────────────────────────────────────────────────
    private function callAnthropic(string $apiKey, string $model, array $snapshot): array
    {
        $payload = [
            'model' => $model, 'max_tokens' => 4000, 'temperature' => 0.3,
            'system' => [['type' => 'text', 'text' => $this->systemPrompt(), 'cache_control' => ['type' => 'ephemeral']]],
            'messages' => [['role' => 'user', 'content' => $this->userPrompt($snapshot)]],
        ];
        $resp = $this->httpPost('https://api.anthropic.com/v1/messages', json_encode($payload, JSON_UNESCAPED_UNICODE), [
            'x-api-key: ' . $apiKey, 'anthropic-version: ' . self::ANTHROPIC_VERSION,
            'content-type: application/json', 'anthropic-beta: prompt-caching-2024-07-31',
        ]);
        $j = json_decode($resp, true);
        if (!is_array($j)) throw new \RuntimeException('Invalid JSON from Anthropic API.');
        if (isset($j['error'])) throw new \RuntimeException('Anthropic API: ' . (is_array($j['error']) ? ($j['error']['message'] ?? '?') : (string) $j['error']));
        $text = '';
        foreach (($j['content'] ?? []) as $b) if (($b['type'] ?? '') === 'text') $text .= $b['text'] ?? '';
        return [$text, ['input' => (int) ($j['usage']['input_tokens'] ?? 0), 'output' => (int) ($j['usage']['output_tokens'] ?? 0)]];
    }

    private function systemPrompt(): string
    {
        return <<<MD
You are "Elite Advisors", a senior strategy + finance partner (McKinsey / BCG caliber) delivering a **monthly Client Strategic Analysis** to a business owner and their advisor. You are handed a consolidated, cross-functional data snapshot for ONE client and must produce a holistic strategic audit: a diagnosis of the state of the business and a concrete plan for resolution, growth, and optimization.

Assess the business across FIVE strategic dimensions, using only the data provided:
  1. Profitability  — revenue, margins (gross/EBITDA/net), cost efficiency
  2. Liquidity & Cash — cash on hand, DSO, DPO, CCC, current/quick ratios, collection realisation
  3. Growth — revenue YoY, customer/volume trend, run-rate vs plan
  4. Efficiency — working-capital use, inventory days, receivables/payables quality, unit economics
  5. Risk & Controls — overdue AR, concentration, book-vs-physical gaps, data-quality flags

## Hard rules
- CITE ONLY figures present in the snapshot JSON. Never invent numbers, names, hosts, or dates. If a block is null, say "not available" for that dimension — do not guess.
- Bold every figure/percentage. Direct advisor tone. No marketing speak.
- Currency: use the snapshot's `currency` field.
- `priority` MUST equal `scorecard.overall` (red→"urgent", amber→"watch", green→"good").
- If `errors`/`stale_blocks` are present, state which data is unavailable/stale and treat it as directional.

## Return format — STRICT JSON only, no prose or fences outside it:
{
  "summary": "One-sentence verdict for the header (lead finding + the KPI that drives it).",
  "priority": "urgent" | "watch" | "good",
  "narrative_md": "A CONCISE strategic narrative in markdown. Structure with '## ' headings: ## Executive Summary (2 tight paragraphs), ## Financial Health, ## Liquidity & Working Capital, ## Growth, ## Efficiency & Operations, ## Risk. Each section 2-4 lines, figure-led, ending each with the implication. No filler.",
  "actions": [
    {"area": "Profitability|Liquidity|Growth|Efficiency|Risk", "diagnosis": "the finding in <=15 words, with the figure", "recommendation": "one concrete action starting with a verb", "impact": "High|Medium|Low", "effort": "High|Medium|Low", "priority": 1}
  ],
  "roadmap_90d": [
    {"horizon": "0-30 days", "theme": "short theme", "items": ["verb-led item tied to a figure", "..."]},
    {"horizon": "30-60 days", "theme": "...", "items": ["..."]},
    {"horizon": "60-90 days", "theme": "...", "items": ["..."]}
  ]
}

Rules for the structured fields:
- `actions`: 5-9 rows, ordered most important first (priority 1 = highest). Every row tied to a real figure. Mix quick wins (High impact / Low effort) and structural moves.
- `roadmap_90d`: exactly three horizons; each with a theme and 2-4 concrete items. 0-30 = stabilize/quick wins; 30-60 = build; 60-90 = scale/optimize.
MD;
    }

    private function userPrompt(array $s): string
    {
        $payload = [
            'currency' => $s['currency'] ?? null,
            'revenue' => $s['revenue'] ?? null, 'pl' => $s['pl'] ?? null,
            'receivables' => $s['receivables'] ?? null, 'reconciliation' => $s['reconciliation'] ?? null,
            'treasury' => $s['treasury'] ?? null, 'payables' => $s['payables'] ?? null,
            'inventory' => $s['inventory'] ?? null, 'operations' => $s['operations'] ?? null,
            'scorecard' => $s['scorecard'] ?? null,
            'errors' => $s['errors'] ?? [], 'stale_blocks' => $s['stale_blocks'] ?? [],
        ];
        return 'Consolidated strategic snapshot for ' . ($s['tenant']['name'] ?? 'client')
             . ' (as_of ' . ($s['as_of'] ?? '?') . "):\n\n"
             . json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)
             . "\n\nReturn the strict JSON object from the system prompt (summary, priority, narrative_md, actions, roadmap_90d). priority MUST equal scorecard.overall.";
    }

    private function parseResponse(string $raw): array
    {
        $raw = trim($raw);
        if (str_starts_with($raw, '```')) $raw = trim((string) preg_replace('/^```(?:json)?\s*|\s*```$/m', '', $raw));
        if (preg_match('/\{.*\}/s', $raw, $m)) $raw = $m[0];
        $j = json_decode($raw, true);
        if (!is_array($j)) throw new \RuntimeException('Could not parse Claude response as JSON.');
        $priority = strtolower((string) ($j['priority'] ?? 'watch'));
        if (!in_array($priority, ['urgent', 'watch', 'good'], true)) $priority = 'watch';
        $actions = [];
        foreach ((array) ($j['actions'] ?? []) as $a) {
            if (!is_array($a)) continue;
            $actions[] = [
                'area' => (string) ($a['area'] ?? ''), 'diagnosis' => (string) ($a['diagnosis'] ?? ''),
                'recommendation' => (string) ($a['recommendation'] ?? ''), 'impact' => (string) ($a['impact'] ?? ''),
                'effort' => (string) ($a['effort'] ?? ''), 'priority' => (int) ($a['priority'] ?? 0),
            ];
        }
        usort($actions, fn ($x, $y) => ($x['priority'] ?: 99) <=> ($y['priority'] ?: 99));
        $roadmap = [];
        foreach ((array) ($j['roadmap_90d'] ?? []) as $r) {
            if (!is_array($r)) continue;
            $roadmap[] = ['horizon' => (string) ($r['horizon'] ?? ''), 'theme' => (string) ($r['theme'] ?? ''), 'items' => array_values(array_map('strval', (array) ($r['items'] ?? [])))];
        }
        return [
            'summary' => (string) ($j['summary'] ?? '— summary missing —'),
            'priority' => $priority,
            'narrative_md' => (string) ($j['narrative_md'] ?? ''),
            'actions' => array_slice($actions, 0, 9),
            'roadmap' => array_slice($roadmap, 0, 3),
        ];
    }

    private function httpPost(string $url, string $body, array $headers): string
    {
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true, CURLOPT_POST => true, CURLOPT_POSTFIELDS => $body,
            CURLOPT_HTTPHEADER => $headers, CURLOPT_TIMEOUT => self::TIMEOUT_SECONDS, CURLOPT_CONNECTTIMEOUT => 15,
            CURLOPT_IPRESOLVE => CURL_IPRESOLVE_V4,
        ]);
        foreach (['curl.cainfo', 'openssl.cafile'] as $k) { $c = ini_get($k); if (is_string($c) && $c !== '' && is_file($c)) { curl_setopt($ch, CURLOPT_CAINFO, $c); break; } }
        $resp = curl_exec($ch);
        if ($resp === false) { $e = curl_error($ch); curl_close($ch); throw new \RuntimeException('HTTP error calling Anthropic: ' . $e); }
        curl_close($ch);
        return (string) $resp;
    }
}
